Keep the best candidate across all configurations.
"""
import os
import re
from collections import Counter
from datetime import datetime

import openpyxl
import pytesseract
from PIL import Image

IMG_DIR = "/app/workspace/dataset/img"
OUT_PATH = "/app/workspace/stat_ocr.xlsx"

PRIORITY_LEVELS = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    ["TOTAL", "AMOUNT", "TOTAL DUE", "AMOUNT DUE",
     "BALANCE DUE", "NETT TOTAL", "NET TOTAL"],
]

STRONG_EXCLUSIONS = ["SUBTOTAL", "SUB TOTAL", "SUB-TOTAL", "CASH TENDERED"]
WEAK_EXCLUSIONS = ["TAX", "GST", "SST", "DISCOUNT", "CHANGE"]

# Accept . or , as decimal separator (OCR sometimes substitutes).
AMOUNT_RE = re.compile(r"(\d{1,3}(?:,\d{3})+\.\d{2}|\d+[.,]\d{2})(?!\d)")

MONTHS = {m: i + 1 for i, m in enumerate(
    ["JAN", "FEB", "MAR", "APR", "MAY", "JUN",
     "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"])}
MONTHS_LONG = {
    "JANUARY": 1, "FEBRUARY": 2, "MARCH": 3, "APRIL": 4, "MAY": 5, "JUNE": 6,
    "JULY": 7, "AUGUST": 8, "SEPTEMBER": 9, "OCTOBER": 10,
    "NOVEMBER": 11, "DECEMBER": 12,
}

OCR_CONFIGS = [(s, p) for s in (2, 3, 1) for p in (6, 4)]


def upscale(img_path, scale):
    img = Image.open(img_path).convert("L")
    if scale == 1:
        return img
    w, h = img.size
    return img.resize((w * scale, h * scale), Image.LANCZOS)


def ocr_text(img_path, psm, scale):
    img = upscale(img_path, scale)
    return pytesseract.image_to_string(img, config=f"--psm {psm}")


def clean_decimal(s):
    return re.sub(r"(\d)\s*\.\s*(\d{2})(?!\d)", r"\1.\2", s)


def normalize_amount(raw):
    s = raw.strip()
    if re.fullmatch(r"\d{1,3}(?:,\d{3})+\.\d{2}", s):
        return s.replace(",", "")
    m = re.fullmatch(r"(\d+)[.,](\d{2})", s)
    if m:
        return f"{m.group(1)}.{m.group(2)}"
    return s


def extract_amounts_from_line(line):
    cleaned = clean_decimal(line)
    return [normalize_amount(m) for m in AMOUNT_RE.findall(cleaned)]


def is_excluded(upper_line):
    for ex in STRONG_EXCLUSIONS:
        if ex in upper_line:
            return True
    # Normalize patterns like "TOTALGST" -> "TOTAL GST" so the startswith
    # check below sees the exclusion keyword directly after TOTAL.
    stripped = upper_line.strip().lstrip("|").lstrip()
    normalized = re.sub(
        r"TOTAL(GST|TAX|SST|DISCOUNT|CHANGE)", r"TOTAL \1", stripped)
    for ex in WEAK_EXCLUSIONS:
        if normalized.startswith(ex):
            return True
        if normalized.startswith("TOTAL " + ex):
            return True
    return False


def looks_like_summary_row(line):
    """GST summary 'Total: 9.85 0.59 10.44' style rows mix net/tax/gross."""
    return len(extract_amounts_from_line(line)) >= 3


def find_all_matches(text):
    """Return list of (priority_level, is_direct, amount) tuples."""
    lines = [l.rstrip() for l in text.split("\n") if l.strip()]
    n = len(lines)
    results = []
    for level, keywords in enumerate(PRIORITY_LEVELS):
        for i, line in enumerate(lines):
            upper = line.upper()
            if not any(kw in upper for kw in keywords):
                continue
            if is_excluded(upper):
                continue
            if looks_like_summary_row(line):
                continue
            amts = extract_amounts_from_line(line)
            if amts:
                # Prefer the largest amount on a direct-match line (the
                # final total typically dominates).
                best = max(amts, key=lambda x: float(x))
                results.append((level, True, best))
            elif i + 1 < n:
                nxt = extract_amounts_from_line(lines[i + 1])
                if nxt:
                    results.append((level, False, nxt[-1]))
    return results


def pick_best(candidates):
    """Pick the candidate with the lowest priority level and direct match.

    Among ties, use the mode across OCR passes; otherwise the maximum.
    """
    if not candidates:
        return None
    # Find best (priority, is_direct) pair; lower priority_level and
    # is_direct=True rank first.
    best_key = min((c[0], not c[1]) for c in candidates)
    group = [c[2] for c in candidates
             if (c[0], not c[1]) == best_key]
    counter = Counter(group)
    most_common = counter.most_common()
    top_count = most_common[0][1]
    top_values = [v for v, c in most_common if c == top_count]
    if len(top_values) == 1:
        return top_values[0]
    return max(top_values, key=lambda x: float(x))


def extract_date(text):
    for m in re.finditer(
            r"(?<!\d)(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{4})(?!\d)", text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if 1990 < y < 2030:
            try:
                return datetime(y, mo, d).strftime("%Y-%m-%d")
            except ValueError:
                continue
    for m in re.finditer(
            r"(?<!\d)(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2})(?!\d)", text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        y = 2000 + y if y < 30 else 1900 + y
        try:
            return datetime(y, mo, d).strftime("%Y-%m-%d")
        except ValueError:
            continue
    for m in re.finditer(
            r"(?<!\d)(\d{1,2})\s+([A-Za-z]{3,9})\s+(\d{4})(?!\d)", text):
        d = int(m.group(1))
        mo_txt = m.group(2).upper()
        y = int(m.group(3))
        mo = MONTHS.get(mo_txt[:3]) or MONTHS_LONG.get(mo_txt)
        if mo is None:
            continue
        try:
            return datetime(y, mo, d).strftime("%Y-%m-%d")
        except ValueError:
            continue
    for m in re.finditer(
            r"(?<!\d)(\d{4})[/\-\.](\d{1,2})[/\-\.](\d{1,2})(?!\d)", text):
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if 1990 < y < 2030:
            try:
                return datetime(y, mo, d).strftime("%Y-%m-%d")
            except ValueError:
                continue
    return None


def pick_best_date(dates):
    counter = Counter(d for d in dates if d)
    if not counter:
        return None
    return counter.most_common(1)[0][0]


def process(img_path):
    candidates = []
    dates = []
    for scale, psm in OCR_CONFIGS:
        txt = ocr_text(img_path, psm=psm, scale=scale)
        candidates.extend(find_all_matches(txt))
        dates.append(extract_date(txt))
    total = pick_best(candidates)
    date = pick_best_date(dates)
    return date, total


def main():
    files = sorted(os.listdir(IMG_DIR))
    files = [f for f in files if f.lower().endswith((".png", ".jpg", ".jpeg"))]

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])

    for f in files:
        path = os.path.join(IMG_DIR, f)
        date_v, total_v = process(path)
        print(f"{f}: date={date_v} total={total_v}")
        ws.append([f, date_v, total_v])

    wb.save(OUT_PATH)
    print(f"\nSaved to {OUT_PATH}")


if __name__ == "__main__":
    main()
