import os
import re
from datetime import datetime

import openpyxl
import pytesseract
from PIL import Image, ImageFilter

IMG_DIR = "/app/workspace/dataset/img"
OUT_PATH = "/app/workspace/stat_ocr.xlsx"

PRIORITY_LEVELS = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    ["TOTAL", "AMOUNT", "TOTAL DUE", "AMOUNT DUE",
     "BALANCE DUE", "NETT TOTAL", "NET TOTAL"],
]

STRONG_EXCLUSIONS = ["SUBTOTAL", "SUB TOTAL", "CASH TENDERED"]
WEAK_EXCLUSIONS = ["TAX", "GST", "SST", "DISCOUNT", "CHANGE"]

AMOUNT_RE = re.compile(r"(\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2})")
NUMBER_RE = re.compile(r"\d+(?:[.,]\d+)?")

MONTHS = {m: i + 1 for i, m in enumerate(
    ["JAN", "FEB", "MAR", "APR", "MAY", "JUN",
     "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"])}
MONTHS_LONG = {
    "JANUARY": 1, "FEBRUARY": 2, "MARCH": 3, "APRIL": 4, "MAY": 5, "JUNE": 6,
    "JULY": 7, "AUGUST": 8, "SEPTEMBER": 9, "OCTOBER": 10,
    "NOVEMBER": 11, "DECEMBER": 12,
}


def upscale(img_path, scale=3):
    img = Image.open(img_path).convert("L")
    w, h = img.size
    return img.resize((w * scale, h * scale), Image.LANCZOS)


def ocr_text(img_path, psm=6, scale=3):
    img = upscale(img_path, scale)
    return pytesseract.image_to_string(img, config=f"--psm {psm}")


def clean_decimal(s):
    """Fix OCR spacing in decimal numbers like '14. 65' -> '14.65'."""
    return re.sub(r"(\d)\s*\.\s*(\d{2})(?!\d)", r"\1.\2", s)


def extract_amount_from_line(line):
    cleaned = clean_decimal(line)
    matches = AMOUNT_RE.findall(cleaned)
    if matches:
        return matches[-1].replace(",", "")
    return None


def is_excluded(upper_line, matched_kw):
    """Return True if line should be skipped despite matching priority kw."""
    for ex in STRONG_EXCLUSIONS:
        if ex in upper_line:
            return True
    # Weak exclusions: only reject if the priority keyword is "TOTAL" or
    # "AMOUNT" alone (ambiguous). "Total Inclusive GST" cases should pass.
    # Rule: skip if the line clearly starts with the exclusion keyword,
    # i.e., the exclusion topic dominates the line.
    stripped = upper_line.strip()
    for ex in WEAK_EXCLUSIONS:
        if stripped.startswith(ex) or stripped.startswith("TOTAL " + ex) \
                or stripped.startswith("TOTAL" + ex):
            return True
    return False


def find_total(text):
    lines = [l.rstrip() for l in text.split("\n") if l.strip()]
    n = len(lines)

    for keywords in PRIORITY_LEVELS:
        best = None
        for i, line in enumerate(lines):
            upper = line.upper()
            matched_kw = None
            for kw in keywords:
                if kw in upper:
                    matched_kw = kw
                    break
            if not matched_kw:
                continue
            if is_excluded(upper, matched_kw):
                continue
            amt = extract_amount_from_line(line)
            if amt is not None:
                best = amt  # Keep updating -> last match on this level wins
                continue
            # Fallback: amount may be on the next line
            if i + 1 < n:
                nxt = clean_decimal(lines[i + 1])
                decimal_matches = AMOUNT_RE.findall(nxt)
                if decimal_matches:
                    best = decimal_matches[-1].replace(",", "")
                else:
                    nums = NUMBER_RE.findall(nxt)
                    if nums:
                        last = nums[-1].replace(",", ".")
                        if "." in last:
                            best = last
        if best is not None:
            return best
    return None


def extract_date(text):
    # DD/MM/YYYY, DD-MM-YYYY, DD.MM.YYYY
    for m in re.finditer(
            r"(?<!\d)(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{4})(?!\d)", text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        try:
            return datetime(y, mo, d).strftime("%Y-%m-%d")
        except ValueError:
            continue
    # DD/MM/YY or DD-MM-YY
    for m in re.finditer(
            r"(?<!\d)(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2})(?!\d)", text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        y = 2000 + y if y < 70 else 1900 + y
        try:
            return datetime(y, mo, d).strftime("%Y-%m-%d")
        except ValueError:
            continue
    # DD Month YYYY  ("05 Jan 2017")
    for m in re.finditer(
            r"(?<!\d)(\d{1,2})\s+([A-Za-z]{3,9})\s+(\d{4})(?!\d)", text):
        d = int(m.group(1))
        mo_txt = m.group(2).upper()
        y = int(m.group(3))
        mo = MONTHS.get(mo_txt[:3]) or MONTHS_LONG.get(mo_txt)
        if mo is None:
            continue
        try:
            return datetime(y, mo, d).strftime("%Y-%m-%d")
        except ValueError:
            continue
    # YYYY-MM-DD / YYYY/MM/DD
    for m in re.finditer(
            r"(?<!\d)(\d{4})[/\-\.](\d{1,2})[/\-\.](\d{1,2})(?!\d)", text):
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        try:
            return datetime(y, mo, d).strftime("%Y-%m-%d")
        except ValueError:
            continue
    return None


def process(img_path):
    # Try multiple OCR passes and pick the first that gives both fields.
    date_found = None
    total_found = None
    for scale in (3, 2):
        for psm in (6, 4):
            txt = ocr_text(img_path, psm=psm, scale=scale)
            if date_found is None:
                date_found = extract_date(txt)
            if total_found is None:
                total_found = find_total(txt)
            if date_found and total_found:
                return date_found, total_found
    return date_found, total_found


def main():
    files = sorted(os.listdir(IMG_DIR))
    files = [f for f in files if f.lower().endswith((".png", ".jpg", ".jpeg"))]

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])

    for f in files:
        path = os.path.join(IMG_DIR, f)
        date_v, total_v = process(path)
        print(f"{f}: date={date_v} total={total_v}")
        ws.append([f, date_v, total_v])

