def is_excluded(upper_line):
    for ex in STRONG_EXCLUSIONS:
        if ex in upper_line:
            return True
    # Normalize patterns like "TOTALGST" -> "TOTAL GST" so the startswith
    # check below sees the exclusion keyword directly after TOTAL.
    stripped = upper_line.strip().lstrip("|").lstrip()
    normalized = re.sub(
        r"TOTAL(GST|TAX|SST|DISCOUNT|CHANGE)", r"TOTAL \1", stripped)
    for ex in WEAK_EXCLUSIONS:
        if normalized.startswith(ex):
            return True
        if normalized.startswith("TOTAL " + ex):
            return True
    return False


def looks_like_summary_row(line):
    """GST summary 'Total: 9.85 0.59 10.44' style rows mix net/tax/gross."""
    return len(extract_amounts_from_line(line)) >= 3


def find_all_matches(text):
    """Return list of (priority_level, is_direct, amount) tuples."""
    lines = [l.rstrip() for l in text.split("\n") if l.strip()]
    n = len(lines)
    results = []
    for level, keywords in enumerate(PRIORITY_LEVELS):
        for i, line in enumerate(lines):
            upper = line.upper()
            if not any(kw in upper for kw in keywords):
                continue
            if is_excluded(upper):
                continue
            if looks_like_summary_row(line):
                continue
            amts = extract_amounts_from_line(line)
            if amts:
                # Prefer the largest amount on a direct-match line (the
                # final total typically dominates).
                best = max(amts, key=lambda x: float(x))
                results.append((level, True, best))
            elif i + 1 < n:
                nxt = extract_amounts_from_line(lines[i + 1])
                if nxt:
                    results.append((level, False, nxt[-1]))
    return results


def pick_best(candidates):
    """Pick the candidate with the lowest priority level and direct match.

    Among ties, use the mode across OCR passes; otherwise the maximum.
    """
    if not candidates:
        return None
    # Find best (priority, is_direct) pair; lower priority_level and
    # is_direct=True rank first.
    best_key = min((c[0], not c[1]) for c in candidates)
    group = [c[2] for c in candidates
             if (c[0], not c[1]) == best_key]
    counter = Counter(group)
    most_common = counter.most_common()
    top_count = most_common[0][1]
    top_values = [v for v, c in most_common if c == top_count]
    if len(top_values) == 1:
        return top_values[0]
    return max(top_values, key=lambda x: float(x))


def extract_date(text):
    for m in re.finditer(
            r"(?<!\d)(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{4})(?!\d)", text):
