            except ValueError:
                continue
    return None


def pick_total(candidates):
    if not candidates:
        return None
    best_key = min((c[0], not c[1]) for c in candidates)
    group = [c[2] for c in candidates if (c[0], not c[1]) == best_key]
    counter = Counter(group)
    most = counter.most_common()
    top = most[0][1]
    top_values = [v for v, c in most if c == top]
    if len(top_values) == 1:
        return top_values[0]
    # Tie: prefer the largest numeric value (usually the final total).
    return max(top_values, key=lambda x: float(x))


def pick_date(dates):
    counter = Counter(d for d in dates if d)
    if not counter:
        return None
    most = counter.most_common()
    top = most[0][1]
    top_values = [v for v, c in most if c == top]
    # Tie: pick latest (most receipts have recent dates).
    return max(top_values)


def process(img_path):
    candidates = []
    dates = []
    for scale, psm in OCR_CONFIGS:
        txt = ocr_text(img_path, psm=psm, scale=scale)
