IMG_DIR = "/app/workspace/dataset/img"
OUT_PATH = "/app/workspace/stat_ocr.xlsx"

PRIORITY_LEVELS = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    ["TOTAL", "AMOUNT", "TOTAL DUE", "AMOUNT DUE",
     "BALANCE DUE", "NETT TOTAL", "NET TOTAL"],
]

STRONG_EXCLUSIONS = ["SUBTOTAL", "SUB TOTAL", "CASH TENDERED"]
WEAK_EXCLUSIONS = ["TAX", "GST", "SST", "DISCOUNT", "CHANGE"]

# Accept either . or , as decimal separator (OCR often reads , for .)
AMOUNT_RE = re.compile(r"(\d{1,3}(?:,\d{3})+\.\d{2}|\d+[.,]\d{2})(?!\d)")

MONTHS = {m: i + 1 for i, m in enumerate(
    ["JAN", "FEB", "MAR", "APR", "MAY", "JUN",
     "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"])}
MONTHS_LONG = {
    "JANUARY": 1, "FEBRUARY": 2, "MARCH": 3, "APRIL": 4, "MAY": 5, "JUNE": 6,
    "JULY": 7, "AUGUST": 8, "SEPTEMBER": 9, "OCTOBER": 10,
    "NOVEMBER": 11, "DECEMBER": 12,
}


def upscale(img_path, scale=3):
    img = Image.open(img_path).convert("L")
    w, h = img.size
    return img.resize((w * scale, h * scale), Image.LANCZOS)


def ocr_text(img_path, psm=6, scale=3):
    img = upscale(img_path, scale)
    return pytesseract.image_to_string(img, config=f"--psm {psm}")


def clean_decimal(s):
    """Fix OCR spacing in decimal numbers like '14. 65' -> '14.65'."""
    return re.sub(r"(\d)\s*\.\s*(\d{2})(?!\d)", r"\1.\2", s)


def normalize_amount(raw):
    """Convert '1,234.56' or '12,60' or '12.60' -> '12.60' (dot-decimal)."""
    s = raw.strip()
    if re.fullmatch(r"\d{1,3}(?:,\d{3})+\.\d{2}", s):
        return s.replace(",", "")
    # "12.60" or "12,60" with exactly 2 decimals
    m = re.fullmatch(r"(\d+)[.,](\d{2})", s)
    if m:
        return f"{m.group(1)}.{m.group(2)}"
    return s


def extract_amounts_from_line(line):
    cleaned = clean_decimal(line)
    return [normalize_amount(m) for m in AMOUNT_RE.findall(cleaned)]


def is_excluded(upper_line):
    """Return True if line is a subtotal/tax/change breakdown line."""
    for ex in STRONG_EXCLUSIONS:
        if ex in upper_line:
            return True
    # Weak exclusion: skip if line's main topic is a tax/discount/change field.
    # Patterns indicating a breakdown line:
    #   "TOTAL GST ...", "TOTAL TAX ...", "TOTAL SST ...",
    #   lines starting with GST/TAX/SST/DISCOUNT/CHANGE,
    #   also "TOTAL DISCOUNT", "TOTAL CHANGE".
    stripped = upper_line.strip().lstrip("|").lstrip()
    # Also normalize "TOTALGST" -> "TOTAL GST"
    normalized = re.sub(
        r"TOTAL(GST|TAX|SST|DISCOUNT|CHANGE)", r"TOTAL \1", stripped)
    for ex in WEAK_EXCLUSIONS:
        if normalized.startswith(ex):
            return True
        if normalized.startswith("TOTAL " + ex):
            return True
    return False


def looks_like_summary_row(line):
    """Detect GST summary 'Total: 9.85 0.59 10.44' style rows."""
    u = line.upper()
    # Lines containing two or more amounts after "TOTAL:" are summaries
    # that typically mix net, tax, and gross.
    amts = extract_amounts_from_line(line)
    if len(amts) >= 3:
        return True
    return False


def find_total(text):
    lines = [l.rstrip() for l in text.split("\n") if l.strip()]
    n = len(lines)

    for keywords in PRIORITY_LEVELS:
        direct = []
        fallback = []
        for i, line in enumerate(lines):
            upper = line.upper()
            if not any(kw in upper for kw in keywords):
                continue
            if is_excluded(upper):
                continue
            if looks_like_summary_row(line):
                continue
            amts = extract_amounts_from_line(line)
            if amts:
                direct.append((i, amts[-1]))
            elif i + 1 < n:
                nxt_line = lines[i + 1]
                nxt_amts = extract_amounts_from_line(nxt_line)
                if nxt_amts:
                    fallback.append((i, nxt_amts[-1]))
        if direct:
            # Prefer the largest; ties broken by last occurrence
            best = max(direct, key=lambda t: (float(t[1]), t[0]))
            return best[1]
        if fallback:
            best = max(fallback, key=lambda t: (float(t[1]), t[0]))
            return best[1]
    return None


def extract_date(text):
    # DD/MM/YYYY, DD-MM-YYYY, DD.MM.YYYY
    for m in re.finditer(
            r"(?<!\d)(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{4})(?!\d)", text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if 1900 < y < 2100:
            try:
                return datetime(y, mo, d).strftime("%Y-%m-%d")
            except ValueError:
                continue
    # DD/MM/YY or DD-MM-YY
    for m in re.finditer(
            r"(?<!\d)(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2})(?!\d)", text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        y = 2000 + y if y < 70 else 1900 + y
        try:
            return datetime(y, mo, d).strftime("%Y-%m-%d")
        except ValueError:
            continue
    # DD Month YYYY  ("05 Jan 2017")
    for m in re.finditer(
            r"(?<!\d)(\d{1,2})\s+([A-Za-z]{3,9})\s+(\d{4})(?!\d)", text):
        d = int(m.group(1))
        mo_txt = m.group(2).upper()
        y = int(m.group(3))
        mo = MONTHS.get(mo_txt[:3]) or MONTHS_LONG.get(mo_txt)
        if mo is None:
            continue
        try:
            return datetime(y, mo, d).strftime("%Y-%m-%d")
        except ValueError:
            continue
    # YYYY-MM-DD / YYYY/MM/DD
    for m in re.finditer(
            r"(?<!\d)(\d{4})[/\-\.](\d{1,2})[/\-\.](\d{1,2})(?!\d)", text):
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if 1900 < y < 2100:
            try:
                return datetime(y, mo, d).strftime("%Y-%m-%d")
            except ValueError:
                continue
    return None


def process(img_path):
    date_found, total_found = None, None
    for scale in (3, 2):
        for psm in (6, 4):
            txt = ocr_text(img_path, psm=psm, scale=scale)
            if date_found is None:
                date_found = extract_date(txt)
            if total_found is None:
                total_found = find_total(txt)
            if date_found and total_found:
                return date_found, total_found
    return date_found, total_found


def main():
    files = sorted(os.listdir(IMG_DIR))
    files = [f for f in files if f.lower().endswith((".png", ".jpg", ".jpeg"))]

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])

    for f in files:
        path = os.path.join(IMG_DIR, f)
        date_v, total_v = process(path)
        print(f"{f}: date={date_v} total={total_v}")
        ws.append([f, date_v, total_v])

    wb.save(OUT_PATH)
    print(f"\nSaved to {OUT_PATH}")


if __name__ == "__main__":
    main()
