    s = raw.strip()
    if re.fullmatch(r"\d{1,3}(?:,\d{3})+\.\d{2}", s):
        return s.replace(",", "")
    # "12.60" or "12,60" with exactly 2 decimals
    m = re.fullmatch(r"(\d+)[.,](\d{2})", s)
    if m:
        return f"{m.group(1)}.{m.group(2)}"
    return s


