        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if 1990 < y < 2030:
            try:
                return datetime(y, mo, d).strftime("%Y-%m-%d")
            except ValueError:
                continue
    return None


def pick_best_date(dates):
    counter = Counter(d for d in dates if d)
    if not counter:
        return None
    return counter.most_common(1)[0][0]


def process(img_path):
    candidates = []
    dates = []
    for scale, psm in OCR_CONFIGS:
        txt = ocr_text(img_path, psm=psm, scale=scale)
        candidates.extend(find_all_matches(txt))
        dates.append(extract_date(txt))
    total = pick_best(candidates)
    date = pick_best_date(dates)
