    "JANUARY": 1, "FEBRUARY": 2, "MARCH": 3, "APRIL": 4, "MAY": 5, "JUNE": 6,
    "JULY": 7, "AUGUST": 8, "SEPTEMBER": 9, "OCTOBER": 10,
    "NOVEMBER": 11, "DECEMBER": 12,
}

OCR_CONFIGS = [(s, p) for s in (2, 3, 1) for p in (6, 4)]


def upscale(img_path, scale):
    img = Image.open(img_path).convert("L")
    if scale == 1:
        return img
    w, h = img.size
    return img.resize((w * scale, h * scale), Image.LANCZOS)


def ocr_text(img_path, psm, scale):
    img = upscale(img_path, scale)
    return pytesseract.image_to_string(img, config=f"--psm {psm}")


def normalize_text(text):
    """Normalize common OCR misreads of the word 'TOTAL'."""
    # 'lutal', 'iutal', 'tutal', 'totai', etc. -> 'TOTAL'
    text = re.sub(r"\b[LlIi][uU][tT][aAiI][lL1Ii]\b", "TOTAL", text)
    text = re.sub(r"\b[tT][uU][tT][aA][lL]\b", "TOTAL", text)
    text = re.sub(r"\b[tT][oO][tT][aA][iIlL1][\s:]", "TOTAL ", text)
    return text


def clean_decimal(s):
    return re.sub(r"(\d)\s*\.\s*(\d{2})(?!\d)", r"\1.\2", s)


def normalize_amount(raw):
    s = raw.strip()
    if re.fullmatch(r"\d{1,3}(?:,\d{3})+\.\d{2}", s):
        return s.replace(",", "")
    m = re.fullmatch(r"(\d+)[.,](\d{2})", s)
    if m:
        return f"{m.group(1)}.{m.group(2)}"
    return s


def extract_amounts_from_line(line):
    cleaned = clean_decimal(line)
    return [normalize_amount(m) for m in AMOUNT_RE.findall(cleaned)]


def is_excluded(upper_line):
    for ex in STRONG_EXCLUSIONS:
        if ex in upper_line:
            return True
    for ex in EXCLUDING_PATTERNS:
        if ex in upper_line:
            return True
    stripped = upper_line.strip().lstrip("|").lstrip()
    normalized = re.sub(
        r"TOTAL(GST|TAX|SST|DISCOUNT|CHANGE)", r"TOTAL \1", stripped)
    for ex in WEAK_EXCLUSIONS:
        if normalized.startswith(ex):
            return True
        if normalized.startswith("TOTAL " + ex):
            return True
    return False


def is_summary_row(line):
    """A line with multiple amounts (>=2) is usually a GST summary row."""
    return len(extract_amounts_from_line(line)) >= 2


def truncate_at_summary(lines):
    """Drop lines starting from the 'GST SUMMARY' marker."""
    for i, line in enumerate(lines):
        u = line.upper()
        if "GST SUMMARY" in u or "TAX SUMMARY" in u:
            return lines[:i]
    return lines


def find_best_candidate(text):
    """Return (priority, is_direct, amount_str) for the best candidate."""
    text = normalize_text(text)
    raw_lines = [l.rstrip() for l in text.split("\n") if l.strip()]
    lines = truncate_at_summary(raw_lines)
    n = len(lines)
    for priority, keywords in enumerate(PRIORITY_LEVELS):
        direct = []
        fallback = []
        for i, line in enumerate(lines):
            upper = line.upper()
            if not any(kw in upper for kw in keywords):
                continue
            if is_excluded(upper):
                continue
            if is_summary_row(line):
                continue
            amts = extract_amounts_from_line(line)
            if amts:
                direct.append(amts[-1])
            elif i + 1 < n:
                nxt = extract_amounts_from_line(lines[i + 1])
                if nxt:
                    fallback.append(nxt[-1])
        if direct:
            return (priority, True, max(direct, key=lambda x: float(x)))
        if fallback:
            return (priority, False, fallback[-1])
    return None


def extract_date(text):
    for m in re.finditer(
            r"(?<!\d)(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{4})(?!\d)", text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if 1990 < y < 2030:
            try:
                return datetime(y, mo, d).strftime("%Y-%m-%d")
            except ValueError:
                continue
    for m in re.finditer(
            r"(?<!\d)(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2})(?!\d)", text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        y = 2000 + y if y < 30 else 1900 + y
        try:
            return datetime(y, mo, d).strftime("%Y-%m-%d")
        except ValueError:
            continue
    for m in re.finditer(
            r"(?<!\d)(\d{1,2})\s+([A-Za-z]{3,9})\s+(\d{4})(?!\d)", text):
        d = int(m.group(1))
        mo_txt = m.group(2).upper()
        y = int(m.group(3))
        mo = MONTHS.get(mo_txt[:3]) or MONTHS_LONG.get(mo_txt)
        if mo is None:
            continue
        try:
            return datetime(y, mo, d).strftime("%Y-%m-%d")
        except ValueError:
            continue
    for m in re.finditer(
            r"(?<!\d)(\d{4})[/\-\.](\d{1,2})[/\-\.](\d{1,2})(?!\d)", text):
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if 1990 < y < 2030:
            try:
                return datetime(y, mo, d).strftime("%Y-%m-%d")
            except ValueError:
                continue
    return None


def pick_total(candidates):
    if not candidates:
        return None
    best_key = min((c[0], not c[1]) for c in candidates)
    group = [c[2] for c in candidates if (c[0], not c[1]) == best_key]
    counter = Counter(group)
    most = counter.most_common()
    top = most[0][1]
    top_values = [v for v, _ in most if _ == top]
    if len(top_values) == 1:
        return top_values[0]
    return max(top_values, key=lambda x: float(x))


def pick_date(dates):
    counter = Counter(d for d in dates if d)
    if not counter:
        return None
    return counter.most_common(1)[0][0]


def process(img_path):
    candidates = []
    dates = []
    for scale, psm in OCR_CONFIGS:
        txt = ocr_text(img_path, psm=psm, scale=scale)
        c = find_best_candidate(txt)
        if c is not None:
            candidates.append(c)
        dates.append(extract_date(txt))
    return pick_date(dates), pick_total(candidates)


def main():
    files = sorted(os.listdir(IMG_DIR))
    files = [f for f in files if f.lower().endswith((".png", ".jpg", ".jpeg"))]

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])

    for f in files:
        path = os.path.join(IMG_DIR, f)
        date_v, total_v = process(path)
        print(f"{f}: date={date_v} total={total_v}")
        ws.append([f, date_v, total_v])

    wb.save(OUT_PATH)
    print(f"\nSaved to {OUT_PATH}")


if __name__ == "__main__":
    main()
